export function createArenaQueue(env){
 const {core:C,escape:esc,icon:I,button:btn,sprite}=env;
 const later=(q,fn,delay)=>setTimeout(()=>{if(env.getQueue()===q)fn();},delay);
 function view(q){const p=q.player,fallback=q.status==='bot';env.modal(`<div class="queue-heading"><span class="eyebrow">ARENA · BUSCA DE ADVERSÁRIO</span><h2 id="modal-title">${fallback?'Adversário encontrado':'Procurando um jogador…'}</h2><p>${fallback?'Seu adversário está pronto para o duelo.':'Buscando alguém com um robô pronto para batalhar.'}</p></div><div class="queue-stage"><div class="queue-player">${sprite(p)}<b>${esc(p.name)}</b><small>NV. ${p.level} · ${p.power} poder</small></div><div class="queue-scanner">${I('arena')}<i></i><span>VS</span></div><div class="queue-opponent">${fallback?sprite(q.opponent.def):`<div class="queue-placeholder">${I('users')}</div>`}<b>${fallback?esc(q.opponent.name):'Aguardando adversário'}</b><small>${fallback?'Controlado pelo jogo':'Prioridade para jogadores reais'}</small></div></div><div class="queue-progress"><i style="width:${Math.min(100,q.seconds/q.timeout*100)}%"></i></div><div class="queue-status" role="status">${fallback?'Preparando a arena…':`${q.seconds}s / ${q.timeout}s · ${env.isDemo?'Fila demonstrativa':'Busca online'}`}</div><div class="notice">${I('info')} ${env.isDemo?'Esta prévia encontra adversários controlados pelo jogo. Partidas entre pilotos dependem do backend.':'O servidor encontra jogadores e resolve o fallback. O cliente não escolhe resultados.'}</div>${btn('Cancelar busca','arena-cancel','','secondary wide')}`,'arena-queue-modal');}
 function opponent(q){const state=env.getState(),roster=(state.arenaRoster||[]).filter(r=>r.enabled!==false&&state.catalog.some(m=>m.id===r.robotId));if(!roster.length)throw new Error('A arena está em manutenção. Nenhuma batalha foi consumida.');
  const rival=roster[Math.floor(Math.random()*roster.length)],def=state.catalog.find(x=>x.id===rival.robotId);
  const attack=Math.max(1,Math.round(q.player.attack*rival.attackFactor)),defense=Math.max(1,Math.round(q.player.defense*rival.defenseFactor));
  return {id:C.uuid(),name:rival.name,def:C.clone(def),isBot:true,kind:'bot',attack,defense,health:Math.max(1,Math.round(q.player.health*rival.healthFactor)),power:Math.floor(attack+defense*.7)};}
 function tick(q){q.seconds++;if(q.seconds>=q.timeout){try{q.status='bot';q.opponent=opponent(q);view(q);env.audio?.play('start');later(q,()=>{env.setQueue(null);env.startBattle(q.opponent);},900);}catch(e){env.setQueue(null);env.closeModal();env.toast(e.message,true);}return;}view(q);later(q,()=>tick(q),1000);}
 async function start(uid){if(env.getQueue()||env.getCombat())return;
  let q;try{const player=C.arenaEligibility(env.getState(),uid);q={id:C.uuid(),uid,player,seconds:0,timeout:env.getState().settings.matchTimeoutSeconds||8,status:'searching'};env.setQueue(q);view(q);
   if(env.isDemo){later(q,()=>tick(q),1000);return;}
   const search=async()=>{if(env.getQueue()!==q)return;try{const result=await env.findOnline(uid);if(env.getQueue()!==q)return;if(result.match){env.setQueue(null);env.startRemote(result.match);return;}q.seconds++;view(q);later(q,search,1000);}catch(e){env.setQueue(null);env.closeModal();env.toast(e.message,true);}};await search();
  }catch(e){if(!q||env.getQueue()===q){env.setQueue(null);env.closeModal();env.toast(e.message,true);}}
 }
 async function cancel(){const q=env.getQueue();if(!q)return;env.setQueue(null);env.closeModal();if(!env.isDemo)try{const result=await env.cancelOnline();if(result.match){env.startRemote(result.match);return;}}catch(e){env.toast(e.message,true);return;}env.toast('Busca cancelada. Nenhuma batalha foi consumida.');}
 return {start,cancel};
}
